Snippet.Contents1:
function checkemail(emailstr) {
    var filter = /^([\w-]+(?:\.[\w-]+)*)@((?:[\w-]+\.)*\w[\w-]{0,66})\.([a-z]{2,6}(?:\.[a-z]{2})?)$/i
    if (filter.test(emailstr)) {
        return true;
    } else {
        return false;
    }
}

