#source: http://www.ruby-lang.org/ # Output "I love Ruby" say = "I love Ruby" puts say
# Output "I *LOVE* RUBY" say['love'] = "*love*" puts say.upcase
# Output "I *love* Ruby" # five times 5.times { puts say }

def fib(n)
  return 1 if n == 0 || n == 1
  return fib(n-1) + fib(n-2)
end
